"""Name/matricula searches must retain text keyboard despite nearby matrícula labels."""
import asyncio
from playwright.async_api import async_playwright
async def main():
 async with async_playwright() as pw:
  b=await pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=await b.new_page(viewport={'width':390,'height':844},is_mobile=True,has_touch=True);await p.goto('http://127.0.0.1:8010/login');await p.wait_for_function("document.querySelector('input[type=text]')?.inputMode==='numeric'");await p.evaluate('''()=>{const d=document.createElement('section');d.id='keyboard-regression';d.innerHTML='<div><label for="kb-mat">Matrícula</label><input id="kb-mat"><label>Nombre o matrícula<input id="kb-name" type="number" inputmode="numeric" maxlength="10" pattern="[0-9]+"></label><label>Nombre del jefe<input id="kb-jefe" inputmode="numeric"></label><label>Importe<input id="kb-amount" type="number"></label><label>Código de seis dígitos<input id="kb-code" inputmode="numeric" pattern="[0-9]{6}"></label></div>';document.body.append(d);}''');await p.wait_for_function("document.querySelector('#kb-name').inputMode==='text'&&document.querySelector('#kb-jefe').inputMode==='text'");await p.locator('#kb-name').fill('Ana Maria 12345');assert await p.locator('#kb-name').input_value()=='Ana Maria 12345';assert await p.locator('#kb-name').get_attribute('pattern') is None;assert await p.locator('#kb-name').get_attribute('maxlength')=='150';assert await p.locator('#kb-mat').get_attribute('inputmode')=='numeric';assert await p.locator('#kb-amount').get_attribute('type')=='number';assert await p.locator('#kb-code').get_attribute('inputmode')=='numeric';await b.close();print('Celular: búsqueda admite nombres y matrícula; campos numéricos y códigos conservan su teclado.',flush=True)
asyncio.run(main())
